from runtime import build, read

from engines.analysis.candidate_fragments import candidate_fragments
from engines.analysis.peak_matching import match_score


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    proteins = request["proteins"]
    modifications = request["modifications"]
    spectra = request["spectra"]
    tolerance = request["tolerance"]

    candidates = list(candidate_fragments(proteins, modifications))
    candidate_count = len(candidates)

    winners = []
    for spectrum in spectra:
        peaks = spectrum["peaks"]
        best = None
        for candidate_id, kind, ions in candidates:
            score = match_score(ions, peaks, tolerance)
            entry = (score, kind, candidate_id)
            if best is None or _better(entry, best):
                best = entry
        score, kind, candidate_id = best
        winners.append({
            "spectrum": spectrum["id"],
            "candidate": candidate_id,
            "kind": kind,
            "score": list(score),
        })

    # Rank winners: descending score tuple, then ascending spectrum ID.
    winners.sort(key=lambda w: (tuple(-x for x in w["score"]), w["spectrum"]))

    decoys = 0
    targets = 0
    for w in winners:
        if w["kind"] == "decoy":
            decoys += 1
        else:
            targets += 1
        w["fdr_numerator"] = decoys
        w["fdr_denominator"] = max(1, targets)

    return {"candidate_count": candidate_count, "winners": winners}


def _better(a, b):
    """Return True when candidate entry a beats b under the published tie rules."""
    score_a, kind_a, id_a = a
    score_b, kind_b, id_b = b
    if score_a != score_b:
        return score_a > score_b
    if kind_a != kind_b:
        return kind_a == "target"
    return id_a < id_b


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

