class TestTransform(unittest.TestCase):
    def test_public_example_via_call_candidate(self):
        payload = {
            "request": {
                "proteins": [{"id": "P1", "sequence": "ACKR"}],
                "modifications": [{"name": "shift", "residue": "C", "shift": 2}],
                "spectra": [
                    {
                        "id": "S1",
                        "peaks": [
                            {"mass": 71, "intensity": 3},
                            {"mass": 103, "intensity": 2},
                            {"mass": 174, "intensity": 4},
                        ],
                    }
                ],
                "tolerance": 0,
            }
        }
        result = call_candidate(
            "engines/analysis/engine.py", "transform", args=[payload, {}]
        )
        self.assertEqual(result["candidate_count"], 9)
        self.assertEqual(len(result["winners"]), 1)
        w = result["winners"][0]
        self.assertEqual(w["spectrum"], "S1")
        self.assertEqual(w["candidate"], "P1/target:1-3:none")
        self.assertEqual(w["kind"], "target")
        self.assertEqual(w["score"], [2, 7, 0])
        self.assertEqual(w["fdr_numerator"], 0)
        self.assertEqual(w["fdr_denominator"], 1)


